import { FormEvent, useState } from 'react';
import {
  JxButton,
  JxInputField,
  JxToastViewport,
  useJxToastQueue,
} from '@jinx-ui/react';

export default function NewsletterSubscribeForm() {
  const toasts = useJxToastQueue();
  const [email, setEmail] = useState('');

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    toasts.push({
      title: 'Готово',
      message: `Письмо отправлено на ${email}`,
      variant: 'success',
    });
    setEmail('');
  };

  return (
    <form
      onSubmit={handleSubmit}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        maxWidth: '420px',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <JxInputField
        label="Электронная почта"
        type="email"
        name="email"
        required
        placeholder="you@example.com"
        helperText="Присылаем письма не чаще раза в неделю"
        value={email}
        onChange={(event) => setEmail(event.target.value)}
      />
      <JxButton variant="primary" type="submit">
        Подписаться
      </JxButton>
      <JxToastViewport
        items={toasts.items}
        onDismiss={toasts.dismiss}
        position="bottom-right"
      />
    </form>
  );
}

